def plan_text(df):
    """The physical plan Spark runs for df, as text."""
    return df._jdf.queryExecution().executedPlan().toString()


def scan_counts(df):
    """Run df once; return (files, rows) that its Parquet scan read."""
    df.collect()
    found = []

    def walk(node):
        if node.nodeName().strip() == "Scan parquet":
            metrics = node.metrics()
            found.append((metrics.apply("numFiles").value(), metrics.apply("numOutputRows").value()))
        children = node.children()
        for i in range(children.size()):
            walk(children.apply(i))

    walk(df._jdf.queryExecution().executedPlan())
    return found[0]


